// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.Map;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.query.explanation.GenericPlanNode;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The medical q9 shape (a MINUS whose composite body is re-opened per left row by the generic path, which never
 * finished on the theme store while the kernel's witness took 94 ms, 2026-11-03): the sequential quote must carry the
 * per-row cursor opens and memo lookups of the MINUS body, and price above the kernel's witness.
 */
public class LmdbNativeCorrelatedBodyQuoteTest {

	private static final String EX = "http://example.org/";

	@TempDir
	File dataDir;

	private SailRepository repository;
	private String previousNative;

	@BeforeEach
	public void setUp() {
		previousNative = System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		repository = new SailRepository(
				new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI encounter = vf.createIRI(EX, "Encounter");
			IRI hasCondition = vf.createIRI(EX, "hasCondition");
			IRI code = vf.createIRI(EX, "code");
			IRI hasObservation = vf.createIRI(EX, "hasObservation");
			IRI value = vf.createIRI(EX, "value");
			conn.begin();
			for (int i = 0; i < 3000; i++) {
				IRI enc = vf.createIRI(EX, "enc" + i);
				IRI cond = vf.createIRI(EX, "cond" + i);
				conn.add(enc, org.eclipse.rdf4j.model.vocabulary.RDF.TYPE, encounter);
				conn.add(enc, hasCondition, cond);
				conn.add(cond, code, vf.createLiteral("DX-" + (200 + i % 3)));
				for (int o = 0; o < 2; o++) {
					IRI obs = vf.createIRI(EX, "obs" + i + "_" + o);
					conn.add(enc, hasObservation, obs);
					conn.add(obs, value, vf.createLiteral(40 + (i + o) % 50));
				}
			}
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
		if (previousNative == null) {
			System.clearProperty("rdf4j.lmdb.nativeQueryEngine.enabled");
		} else {
			System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", previousNative);
		}
	}

	private static final String COUNT_MINUS = "PREFIX ex: <" + EX + ">\n"
			+ "SELECT (COUNT(DISTINCT ?enc) AS ?count) WHERE {\n"
			+ "  ?enc a ex:Encounter ; ex:hasCondition ?cond .\n"
			+ "  ?cond ex:code ?condCode .\n"
			+ "  FILTER(?condCode IN (\"DX-200\", \"DX-201\"))\n"
			+ "  MINUS { ?enc ex:hasObservation ?obs . ?obs ex:value ?value . FILTER(?value < 60) }\n"
			+ "}";

	private static final String ROWS_MINUS = "PREFIX ex: <" + EX + ">\n"
			+ "SELECT ?enc WHERE {\n"
			+ "  ?enc a ex:Encounter ; ex:hasCondition ?cond .\n"
			+ "  ?cond ex:code ?condCode .\n"
			+ "  FILTER(?condCode IN (\"DX-200\", \"DX-201\"))\n"
			+ "  MINUS { ?enc ex:hasObservation ?obs . ?obs ex:value ?value . FILTER(?value < 60) }\n"
			+ "}";

	@Test
	public void theSequentialMinusBodyIsPricedPerRowAndAboveTheKernelWitness() {
		GenericPlanNode plan;
		try (SailRepositoryConnection conn = repository.getConnection()) {
			plan = conn.prepareTupleQuery(ROWS_MINUS).explain(Explanation.Level.Telemetry).toGenericPlanNode();
		}
		Map<String, Map<String, Double>> features = NativeProposalFeatures.offering(plan, "nestedLoop");
		Map<String, Double> costs = NativeProposalFeatures.costs(plan, "nestedLoop");
		Map<String, Double> sequential = features.get("nestedLoop");
		// the body's two patterns are opened and read to a first match per left row, with a memo lookup each
		assertThat(sequential.getOrDefault("BRANCH_OPEN", 0D)).as("sequential: %s", features).isGreaterThan(0D);
		assertThat(sequential.getOrDefault("MEMBERSHIP_TEST", 0D)).as("sequential: %s", features)
				.isGreaterThan(0D);
		String kernel = features.containsKey("irKernel") ? "irKernel" : "irKernelInterpreted";
		assertThat(features).as("a kernel at the same decision: %s", features).containsKey(kernel);
		assertThat(features.get(kernel).getOrDefault("BRANCH_OPEN", 0D)).isZero();
		assertThat(costs.get("nestedLoop")).as("prices: %s", costs).isGreaterThanOrEqualTo(1.2D * costs.get(kernel));
	}

	@Test
	public void theAggregateKernelsQuoteTheMinusBodyAsAWitnessBelowTheSequentialPath() {
		GenericPlanNode plan;
		try (SailRepositoryConnection conn = repository.getConnection()) {
			plan = conn.prepareTupleQuery(COUNT_MINUS).explain(Explanation.Level.Telemetry).toGenericPlanNode();
		}
		Map<String, Map<String, Double>> features = NativeProposalFeatures.offering(plan, "nestedLoop");
		Map<String, Double> costs = NativeProposalFeatures.costs(plan, "nestedLoop");
		String kernel = features.containsKey("irAggregate") ? "irAggregate" : "irAggregateInterpreted";
		assertThat(features).as("an aggregate kernel at the same decision: %s", features).containsKey(kernel);
		// the kernel's witness: seeks, no cursor opens, no memo; and it carries the join's access work at all
		assertThat(features.get(kernel).getOrDefault("INDEX_SEEK", 0D)).as("kernel: %s", features)
				.isGreaterThan(0D);
		assertThat(features.get(kernel).getOrDefault("BRANCH_OPEN", 0D)).isZero();
		assertThat(costs.get("nestedLoop")).as("prices: %s", costs).isGreaterThanOrEqualTo(1.2D * costs.get(kernel));
	}
}
